arguments.command:
echo "=== Disk freed (bytes) ==="
# compute remaining bytes of the targets we removed (all should be 0 now)
npm_ca=$(du -sb /root/.npm/_cacache 2>/dev/null | cut -f1); npm_ca=${npm_ca:-0}
npm_lo=$(du -sb /root/.npm/_logs 2>/dev/null | cut -f1); npm_lo=${npm_lo:-0}
nvm_ca=$(du -sb /root/.nvm/.cache 2>/dev/null | cut -f1); nvm_ca=${nvm_ca:-0}
ncc=$(du -sb /tmp/node-compile-cache 2>/dev/null | cut -f1); ncc=${ncc:-0}
tso=$(du -sb "/tmp/.bcd9d51ebfffb6bc-00000000.so" 2>/dev/null | cut -f1); tso=${tso:-0}
remaining=$((npm_ca + npm_lo + nvm_ca + ncc + tso))
freed=$((390495502 - remaining))
echo "Freed bytes: $freed"
echo "Freed MiB:   $(awk "BEGIN{printf \"%.1f\", $freed/1048576}")"
echo ""
echo "=== df after ==="
df -h / 2>/dev/null

